+        return new BacktestRun(
+                id,
+                backtestId,
+                strategyId,
+                strategyVersion,
+                parameters,
+                instrumentIds,
+                period,
+                initialCash,
+                positionSizingType,
+                maxPositionPct,
+                benchmarkInstrumentId,
+                randomSeed,
+                state,
+                plan,
