+        requireNotFinal(RunStatus.FAILED);
+        if (failureCode == null || failureCode.isBlank()) {
+            throw new IllegalArgumentException("failureCode must not be blank");
+        }
+        return withState(
+                new RunState(
+                        RunStatus.FAILED,
+                        state.attempt(),
+                        state.currentExecutionId(),
+                        false,
+                        state.progress(),
+                        failureCode,
+                        failureMessage));
+    }
