+@Validated
+@ConfigurationProperties(prefix = "thorp.backtest.limits")
+public class BacktestLimitProperties {
+
+    /** 한 사용자가 대기시켜 둘 수 있는 <b>단건</b> 실행 수. 탐색 묶음은 007 의 발행 창이 통제하므로 세지 않는다. */
