+    private boolean provisional = true;
+
+    public Integer getMaxQueuedPerUser() {
+        return maxQueuedPerUser;
+    }
+
+    public void setMaxQueuedPerUser(Integer maxQueuedPerUser) {
+        this.maxQueuedPerUser = maxQueuedPerUser;
