+    }
+
+    public void setMaxQueuedAnonymous(Integer maxQueuedAnonymous) {
+        this.maxQueuedAnonymous = maxQueuedAnonymous;
+    }
+
+    public Long getMaxRunSeconds() {
+        return maxRunSeconds;
+    }
+
+    public void setMaxRunSeconds(Long maxRunSeconds) {
