+    }
+
+    public void setStaleRunSeconds(Long staleRunSeconds) {
+        this.staleRunSeconds = staleRunSeconds;
+    }
+
+    public Long getCancelGraceSeconds() {
+        return cancelGraceSeconds;
+    }
