+                    WHERE run.id = r.runId
+                      AND run.status IN (
+                          com.ssafy.thorp.backtest.domain.model.RunStatus.COMPLETED,
+                          com.ssafy.thorp.backtest.domain.model.RunStatus.FAILED,
+                          com.ssafy.thorp.backtest.domain.model.RunStatus.CANCELLED))
