+public class BacktestReuseEventJpaEntity {
+
+    @Id
+    @GeneratedValue(
+            strategy = GenerationType.SEQUENCE,
+            generator = "backtest_reuse_event_seq_generator")
+    @SequenceGenerator(
+            name = "backtest_reuse_event_seq_generator",
+            sequenceName = "backtest_reuse_event_seq",
