+        EXAMPLE_PRESENT,
+        EXAMPLE_SECTOR_COUNT,
+        EXAMPLE_SECTOR_IN_MAP,
+        EXAMPLE_WEIGHT_SUM,
+        TERM_BLOCKS_MATCH,
+        TERM_SENTENCE,
+        FORBIDDEN_EXPRESSION,
+        RESULT_NUMBER_OUTSIDE_HYPOTHETICAL
+    }
+
+    public PublishCheckFailure {
+        Objects.requireNonNull(check, "check must not be null");
