+                snapshot.title(),
+                snapshot.question(),
+                snapshot.readingOrder(),
+                blocksToJson(snapshot.bodyBlocks()),
+                exampleToJson(snapshot.example()),
+                sourcesToJson(snapshot.sources()),
+                snapshot.terms().stream()
+                        .map(
+                                term ->
+                                        new TermJson(
+                                                term.termId().value(),
+                                                term.label(),
+                                                term.sentence()))
+                        .toList(),
