+
+    static Optional<MarketObservation> observation(
+            String value, String unit, String period, boolean monthly) {
+        if (value == null
+                || value.isBlank()
+                || value.equals("-")
+                || value.equals(".")
+                || value.equals("...")) return Optional.empty();
+        try {
+            String date =
+                    monthly
