+
+    protected MyRecordJpaEntity() {}
+
+    MyRecordJpaEntity(
+            Long ownerId,
+            RecordKind kind,
+            Long analysisRunId,
+            Long paramSearchId,
+            Long regimeLogId,
+            String name,
+            String[] sectorCodes,
+            String[] strategyIds,
