+    public Instant now() {
+        return clock.instant();
+    }
+
+    private ParsedChannel parse(byte[] body, RssNewsSource source) {
+        XMLInputFactory factory = policy.secureXmlInputFactory();
+        List<CollectedNewsItem> items = new ArrayList<>();
