+                .collect(java.util.stream.Collectors.toUnmodifiableSet());
+    }
+
+    /** 해외 보도를 수집할 수 있는 국내 연결 주제 키. */
+    public Set<String> domesticLinkTopicKeys() {
+        return topics.stream()
+                .filter(Topic::domesticLink)
+                .map(Topic::topicKey)
+                .collect(java.util.stream.Collectors.toUnmodifiableSet());
+    }
+}

