+        public Publisher(
+                String publisherKey,
+                String displayName,
+                String language,
+                String registeredDomain,
+                String rssUrl,
+                boolean enabled,
+                java.util.List<String> topicKeys) {
+            this(
+                    publisherKey,
+                    displayName,
+                    language,
+                    registeredDomain,
+                    rssUrl,
+                    enabled,
+                    topicKeys,
+                    null,
+                    null);
+        }
+
+        /** 기사 분류 값을 주는 매체. 채널 주제를 따로 적지 않는다. */
+        public Publisher(
+                String publisherKey,
+                String displayName,
+                String language,
+                String registeredDomain,
+                String rssUrl,
+                boolean enabled) {
+            this(
+                    publisherKey,
+                    displayName,
+                    language,
+                    registeredDomain,
+                    rssUrl,
+                    enabled,
+                    java.util.List.of());
+        }
