+                                        topic.displayName(),
+                                        topic.domesticLink(),
+                                        topic.sectorIds()));
+    }
+
+    @Override
+    public Set<String> domesticLinkTopicKeys() {
+        return registry.domesticLinkTopicKeys();
+    }
+}

